entries[53489] = { ["name"] = "Die Kunst des Krieges", ["text"] = "Sofort\nErhöht sowohl den kritischen Schaden Eurer Richturteilszauber, als auch den Eurer Zauber 'Kreuzfahrerstoß' und 'Göttlicher Sturm' um 750%. Zudem wird, wenn Eure Nahkampfangriffe kritisch treffen, die Zauberzeit Eures nächsten Wirkens von 'Lichtblitz' oder 'Exorzismus' um 0.75 Sek. verringert." }
entries[53601] = { ["name"] = "Geheiligter Schild", ["text"] = "12% von Grundmana 40 Meter Reichweite\nSofort\nJedes Mal, wenn das Ziel Schaden erleidet, wird es von einem geheiligten Schild umhüllt, der 500 Schaden absorbiert und die Chance des Paladins, mit 'Lichtblitz' einen kritischen Treffer zu erzielen, 6 Sek. lang um 50% erhöht. Dieser Effekt kann nur einmal alle 6 Sek. auftreten. Hält 30 Sek. lang an. Es kann immer nur jeweils ein Ziel mit diesem Zauber belegt sein." }
entries[53672] = { ["name"] = "Lichtenergie", ["text"] = "Sofort\nKritische Treffer Eures Zaubers 'Heiliger Schock' verringern die Zauberzeit Eures nächsten Wirkens von 'Lichtblitz' um 0.75 Sek. oder erhöhen die kritische Trefferchance Eures nächsten Wirkens von 'Heiliges Licht' um 10%." }
